use axum::{extract::{ConnectInfo, State}, http::{HeaderMap, StatusCode}, routing::post, Json, Router};
use gwt::project_runtime::{client::ProjectRuntimeClient, events::{OwnerCommand, OwnerRequest}};
use gwt_core::daemon::{DaemonEndpoint, RuntimeScope, RuntimeTarget};
use serde_json::json;
use std::{net::SocketAddr, sync::{atomic::{AtomicUsize, Ordering}, mpsc, Arc}, time::{Duration, Instant}};

#[derive(Clone)]
struct Fixture {
    requests: Arc<AtomicUsize>,
    received: mpsc::Sender<u16>,
    response: Arc<tokio::sync::Barrier>,
}

async fn command(
    State(fixture): State<Fixture>, ConnectInfo(peer): ConnectInfo<SocketAddr>,
    headers: HeaderMap, Json(request): Json<OwnerRequest>,
) -> Result<Json<serde_json::Value>, StatusCode> {
    if headers.get("authorization").and_then(|value| value.to_str().ok()) != Some("Bearer inert-fixture") {
        return Err(StatusCode::UNAUTHORIZED);
    }
    assert!(matches!(request.command, OwnerCommand::Health | OwnerCommand::Resize { .. }));
    let index = fixture.requests.fetch_add(1, Ordering::SeqCst);
    fixture.received.send(peer.port()).unwrap();
    if index != 0 { fixture.response.wait().await; }
    Ok(Json(json!({"ok": true})))
}

fn main() {
    for callers in [1, 2, 12] {
        let server = tokio::runtime::Builder::new_multi_thread().worker_threads(2).enable_all().build().unwrap();
        let (received, arrivals) = mpsc::channel();
        let response = Arc::new(tokio::sync::Barrier::new(callers + 1));
        let requests = Arc::new(AtomicUsize::new(0));
        let fixture = Fixture { requests: requests.clone(), received, response: response.clone() };
        let (shutdown, stop) = tokio::sync::oneshot::channel();
        let (address, served) = server.block_on(async {
            let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
            let address = listener.local_addr().unwrap();
            let router = Router::new().route("/private/project/command", post(command)).with_state(fixture);
            let served = tokio::spawn(async move {
                axum::serve(listener, router.into_make_service_with_connect_info::<SocketAddr>())
                    .with_graceful_shutdown(async { let _ = stop.await; }).await.unwrap();
            });
            (address, served)
        });
        let scope = RuntimeScope::new("inert-probe", "inert-probe", std::env::current_dir().unwrap(), RuntimeTarget::Host).unwrap();
        let mut endpoint = DaemonEndpoint::new(scope, std::process::id(), "fixture".into(), "inert-fixture".into(), "fixture".into());
        endpoint.project_transport_url = Some(format!("http://{address}"));
        let client = ProjectRuntimeClient::new(&endpoint).unwrap();
        let (finish_first, first_finished) = tokio::sync::oneshot::channel();
        let (first_ready, ready) = mpsc::channel();
        let initial = client.clone();
        let first = std::thread::spawn(move || {
            let runtime = tokio::runtime::Builder::new_current_thread().enable_all().build().unwrap();
            runtime.block_on(async {
                initial.command(OwnerCommand::Health).await.unwrap();
                first_ready.send(()).unwrap();
                let _ = first_finished.await;
            });
            drop(runtime);
        });
        ready.recv_timeout(Duration::from_secs(10)).unwrap();
        let first_port = arrivals.recv_timeout(Duration::from_secs(10)).unwrap();
        let started = Instant::now();
        let pending = (0..callers).map(|index| {
            let client = client.clone();
            std::thread::spawn(move || {
                let runtime = tokio::runtime::Builder::new_current_thread().enable_all().build().unwrap();
                runtime.block_on(client.command(OwnerCommand::Resize { id: format!("inert-{index}"), incarnation: 1, cols: 80, rows: 24 }))
            })
        }).collect::<Vec<_>>();
        let ports = (0..callers).map(|_| arrivals.recv_timeout(Duration::from_secs(10)).unwrap()).collect::<Vec<_>>();
        finish_first.send(()).unwrap();
        first.join().unwrap();
        server.block_on(response.wait());
        let replies = pending.into_iter().map(|thread| thread.join().unwrap()).collect::<Vec<_>>();
        println!("{}", json!({"case":"reply_after_first_runtime_dropped", "command_kind":"resize", "callers":callers,
            "reused_first_runtime_connection":ports.iter().filter(|port| **port == first_port).count(),
            "passed":replies.iter().filter(|result| result.is_ok()).count(),
            "failed":replies.iter().filter(|result| result.is_err()).count(),
            "generic_send_errors":replies.iter().filter(|result| result.as_ref().err().is_some_and(|error| error.starts_with("error sending request"))).count(),
            "server_requests":requests.load(Ordering::SeqCst), "elapsed_ms":started.elapsed().as_millis()}));
        drop(client);
        shutdown.send(()).unwrap();
        server.block_on(served).unwrap();
    }
}

