#[derive(Clone)]
struct ProbeClient {
    http: reqwest::Client,
    url: String,
    key: String,
}
impl ProbeClient {
    fn new(endpoint: &DaemonEndpoint) -> Result<Self, String> {
        let http = if std::env::args().any(|value| value == "no-idle") {
            reqwest::Client::builder().pool_max_idle_per_host(0).build().map_err(|error| error.to_string())?
        } else { reqwest::Client::new() };
        Ok(Self { http, url: endpoint.project_transport_url.clone().unwrap(), key: endpoint.scope.repo_hash.clone() })
    }
    async fn command(&self, command: OwnerCommand) -> Result<serde_json::Value, String> {
        let response = self.http.post(format!("{}/private/project/command", self.url))
            .bearer_auth("inert-fixture")
            .timeout(std::time::Duration::from_secs(120))
            .json(&OwnerRequest { project_key: self.key.clone(), command })
            .send().await.map_err(|error| observed_error("send", error))?;
        response.json().await.map_err(|error| observed_error("body", error))
    }
}
fn observed_error(phase: &'static str, error: reqwest::Error) -> String {
    println!("{}", json!({"client":"raw_reqwest_control", "phase":phase,
        "is_timeout":error.is_timeout(), "is_connect":error.is_connect(),
        "is_request":error.is_request(), "is_body":error.is_body(), "is_decode":error.is_decode()}));
    error.to_string()
}

